<!-- Generated by Trae Work -->
<script setup>
/**
 * 大世界管理 (WorldEditor)
 *
 * 后台大世界管理页面，使用 CrudTable + 【种族模板导入器】+【势力模板导入器】双面板。
 *
 *  【种族】= 生灵的血脉/物种分类：人族 → 中原人 / 精灵族 → 高等精灵 / 龙族 → 红龙
 *  【势力】= 组织团体：宗门 / 王国 / 商会 / 公会 / 教派 / 骑士团 / 联盟
 *
 *  两种模板都支持 parent_faction 多级嵌套，导入时会先创建父级、再创建子级。
 */
import { onMounted, ref, computed } from 'vue'
import CrudTable from '@/components/admin/CrudTable.vue'
import { worldApi, factionApi } from '@/api'
import { useWorldDataStore } from '@/stores/worldData'
import PRESET_RACE_TEMPLATES, { getRaceTemplateList, getRaceTemplateByKey } from '@/data/presetRaces'
import PRESET_FORCE_TEMPLATES, { getForceTemplateList, getForceTemplateByKey } from '@/data/presetForces'

const worldData = useWorldDataStore()

/* ==================== 表格列配置 ==================== */
const columns = [
  { key: 'order', label: '排序', width: '70px', sortable: true },
  { key: 'name', label: '世界名称', sortable: true },
  { key: 'slug', label: 'URL 别名', width: '140px' },
  { key: 'subtitle', label: '副标题' },
  { key: 'tone', label: '基调', width: '120px' },
  { key: 'is_active', label: '状态', width: '90px' },
  { key: 'updated_at', label: '更新时间', width: '160px', sortable: true },
]

/* ==================== 表单字段 ==================== */
const formFields = [
  { key: 'name', label: '世界名称', type: 'text', required: true, placeholder: '请输入大世界名称，如：残响界' },
  { key: 'slug', label: 'URL 别名', type: 'text', required: true, placeholder: '英文/数字/连字符，如：canxiangjie' },
  { key: 'subtitle', label: '副标题', type: 'text', placeholder: '碎片之力构筑的万千世界' },
  { key: 'tone', label: '基调', type: 'text', placeholder: '黑暗史诗 / 轻松冒险' },
  { key: 'description', label: '世界描述', type: 'rich', fullWidth: true, placeholder: '请输入大世界的详细描述' },
  { key: 'is_active', label: '是否启用', type: 'switch', default: true },
  { key: 'order', label: '排序', type: 'number', default: 0, min: 0, placeholder: '数字越小越靠前' },
]

/* ===== 顶部模板导入器：目标大世界选择 ===== */
const selectedWorldSlug = ref('')
const worldList = ref([])

/* ==================== CRUD 函数 ==================== */
const _rawFetchFn = (params) => worldApi.list(params)
const fetchFn = async (params) => {
  const res = await _rawFetchFn(params)
  worldList.value = res?.data?.results || []
  if (!selectedWorldSlug.value && worldList.value.length) {
    selectedWorldSlug.value = worldList.value[0].slug
  }
  return res
}
const createFn = (data) => worldApi.create(data)
const updateFn = (id, data, row) => worldApi.update((row && (row.slug || row.id)) || id, data)
const deleteFn = (id, row) => worldApi.delete((row && (row.slug || row.id)) || id, data)

function handleRefresh() { worldData.clearAllCache() }
onMounted(() => handleRefresh())

/* =========================================================================
 *  通用：顶部快捷按钮触发对应面板（种族 / 势力）
 * ========================================================================= */
const activePanel = ref('')   // '' | 'race' | 'force'
const importPanelOpen = ref(false)
const targetWorld = ref(null)
const selectedTemplateKey = ref('')
const importOverwrite = ref(false)
const importing = ref(false)
const importLog = ref([])

/** 从顶部按钮打开面板 */
function openRacePanelFromTop() { openPanel('race') }
function openForcePanelFromTop() { openPanel('force') }
function openPanel(which, worldRow) {
  const world = worldRow || worldList.value.find((w) => w.slug === selectedWorldSlug.value)
  if (!world) { alert('请先选择一个大世界，或先创建一个大世界。'); return }
  targetWorld.value = { slug: world.slug, name: world.name, id: world.id }
  activePanel.value = which
  selectedTemplateKey.value = ''
  importOverwrite.value = false
  importLog.value = []
  importPanelOpen.value = true
}
function closeImportPanel() {
  if (importing.value) return
  importPanelOpen.value = false
  targetWorld.value = null
  selectedTemplateKey.value = ''
  importLog.value = []
  activePanel.value = ''
}

/* ===== 面板专属：模板列表 + 预览 ===== */
const currentCategory = computed(() => (activePanel.value === 'race' ? 'race' : 'force'))
const currentTemplateList = computed(() => (currentCategory.value === 'race' ? getRaceTemplateList() : getForceTemplateList()))
const currentCategoryLabel = computed(() => (currentCategory.value === 'race' ? '种族' : '势力'))

const templatePreview = computed(() => {
  if (!selectedTemplateKey.value) return null
  const tpl = currentCategory.value === 'race'
    ? getRaceTemplateByKey(selectedTemplateKey.value)
    : getForceTemplateByKey(selectedTemplateKey.value)
  if (!tpl) return null
  const items = tpl.races || tpl.forces || []
  const byLevel = { S: [], E: [], A: [], B: [], C: [], unknown: [] }
  items.forEach((f) => {
    const lvl = f.level || 'unknown'
    if (!byLevel[lvl]) byLevel[lvl] = []
    byLevel[lvl].push(f)
  })
  // 按层级分布统计
  const roots = items.filter((x) => !x.parent).length
  const subs = items.filter((x) => x.parent).length
  return {
    name: tpl.templateName || tpl.name,
    icon: tpl.templateIcon || tpl.icon,
    desc: tpl.templateDesc || tpl.desc,
    groups: byLevel,
    totalCount: items.length,
    roots, subs,
  }
})

/* =========================================================================
 *  通用导入执行：先父后子 + 建立 parent_faction 关联
 * ========================================================================= */
async function runImport() {
  if (!targetWorld.value || !selectedTemplateKey.value) return
  const cat = currentCategory.value
  const tpl = cat === 'race'
    ? getRaceTemplateByKey(selectedTemplateKey.value)
    : getForceTemplateByKey(selectedTemplateKey.value)
  if (!tpl) return
  const items = (tpl.races || tpl.forces || []).slice()

  importing.value = true
  importLog.value = []
  const pushLog = (type, msg) => {
    importLog.value.push({ type, msg, time: new Date().toLocaleTimeString() })
  }

  pushLog('info', `开始将${currentCategoryLabel.value}模板「${templatePreview.value.name}」(${items.length}项)导入「${targetWorld.value.name}」...`)
  pushLog('info', `层级结构：根节点 ${templatePreview.value.roots} 个，子节点 ${templatePreview.value.subs} 个`)

  let created = 0, updated = 0, skipped = 0, failed = 0
  const key2id = {}   // 模板 key → 实际创建/已存在 Faction.id，用于 parent_faction 关联

  /** 拓扑：一级级迭代，确保父先于子创建 */
  let remaining = items.slice()
  for (let pass = 0; pass < 5 && remaining.length; pass++) {
    const nextRound = []
    for (const item of remaining) {
      // 若有父且父尚未处理，放至下一轮
      if (item.parent && !key2id[item.parent]) { nextRound.push(item); continue }
      try {
        const existRes = await factionApi.list({
          world: targetWorld.value.slug, name: item.name, page_size: 1,
        })
        const existRow = (existRes?.data?.results || [])[0] || null
        const payload = {
          world: targetWorld.value.slug,
          category: item.category || cat,
          name: item.name,
          type: item.type || (cat === 'race' ? 'other_race' : 'other_force'),
          level: item.level || 'B',
          description: item.description || '',
          territory: item.territory || '',
          population: item.population || 0,
          leader: item.leader || '',
          traits: item.traits || '',
          ideology: item.ideology || '',
          parent_faction: (item.parent && key2id[item.parent]) || (existRow?.parent_faction?.id ?? existRow?.parent_faction ?? null),
        }
        if (existRow) {
          if (!importOverwrite.value) {
            skipped++; key2id[item.key] = existRow.id
            pushLog('skip', `跳过「${item.name}」已存在`)
          } else {
            await factionApi.update(existRow.id, payload)
            updated++; key2id[item.key] = existRow.id
            pushLog('update', `更新「${item.name}」(${item.level})`)
          }
        } else {
          const r = await factionApi.create(payload)
          created++
          const id = r?.data?.id || r?.id
          if (id) key2id[item.key] = id
          pushLog('create', `新建「${item.name}」(${item.level})${item.parent ? ' → 挂于父节点' : ''}`)
        }
      } catch (e) {
        failed++
        const errMsg = e?.response?.data?.detail || e?.message || '未知错误'
        pushLog('error', `失败「${item.name}」：${errMsg}`)
      }
    }
    if (nextRound.length === remaining.length) {
      // 有无法解决的父引用，直接报错处理
      nextRound.forEach((x) => {
        failed++
        pushLog('error', `失败「${x.name}」：找不到父节点 key=${x.parent}（可能模板结构有误）`)
      })
      break
    }
    remaining = nextRound
  }

  pushLog('info', `✅ 导入完成：新建 ${created}，更新 ${updated}，跳过 ${skipped}，失败 ${failed}。`)
  importing.value = false
  worldData.clearAllCache()
}

const previewTotalCount = computed(() => {
  const g = templatePreview.value?.groups || {}
  return ['S', 'E', 'A', 'B', 'C', 'unknown'].reduce((s, k) => s + (g[k]?.length || 0), 0)
})
</script>

<template>
  <div class="admin-page">
    <!-- ============================================================
         顶部：种族 + 势力 双导入器（两卡片并排）
         ============================================================ -->
    <div class="importer-row">
      <!-- 种族模板导入 -->
      <div class="template-importer card importer--race">
        <div class="importer-header">
          <div class="importer-title-wrap">
            <span class="importer-icon importer-icon--race">🧬</span>
            <div>
              <h3 class="importer-title gold-shimmer-text">种族模板·万族谱系</h3>
              <p class="importer-subtitle">
                5 大成熟体系共 <strong>310+</strong> 种生灵分支：修真万族 / 魔兽种族 / 山海经洪荒 / 异世界 ACG / D&D 西幻。
                含多层级（人族 → 中原人 / 精灵族 → 高等精灵 / 龙族 → 红龙）。
              </p>
            </div>
          </div>
          <div class="template-badges">
            <span v-for="t in getRaceTemplateList()" :key="t.key" class="tpl-badge" :title="t.desc">
              <span class="tpl-icon">{{ t.icon }}</span>
              <span class="tpl-name">{{ t.name }}</span>
              <span class="tpl-count">{{ t.raceCount }}种</span>
            </span>
          </div>
        </div>
        <div class="importer-controls">
          <div class="controls-label"><span class="cl-icon">🌌</span>导入到：</div>
          <select class="world-select" v-model="selectedWorldSlug" :disabled="!worldList.length">
            <option v-if="!worldList.length" value="">（先创建大世界）</option>
            <option v-for="w in worldList" :key="w.slug" :value="w.slug">{{ w.name }} ({{ w.slug }})</option>
          </select>
          <button class="import-btn import-btn--race" type="button" :disabled="!worldList.length || !selectedWorldSlug" @click="openRacePanelFromTop">
            <span class="ib-icon">🧬</span><span>一键导入种族模板…</span>
          </button>
        </div>
      </div>

      <!-- 势力模板导入 -->
      <div class="template-importer card importer--force">
        <div class="importer-header">
          <div class="importer-title-wrap">
            <span class="importer-icon importer-icon--force">🏰</span>
            <div>
              <h3 class="importer-title gold-shimmer-text">势力模板·组织团体</h3>
              <p class="importer-subtitle">
                5 大体系共 <strong>150+</strong> 组织：宗门/王国/商会/公会/教派/骑士团/联盟。
                多层级（正道联盟 → 天剑门 / 联盟 → 暴风王国 / 三教 → 阐教）。
              </p>
            </div>
          </div>
          <div class="template-badges">
            <span v-for="t in getForceTemplateList()" :key="t.key" class="tpl-badge" :title="t.desc">
              <span class="tpl-icon">{{ t.icon }}</span>
              <span class="tpl-name">{{ t.name }}</span>
              <span class="tpl-count">{{ t.forceCount }}个</span>
            </span>
          </div>
        </div>
        <div class="importer-controls">
          <div class="controls-label"><span class="cl-icon">🌌</span>导入到：</div>
          <select class="world-select" v-model="selectedWorldSlug" :disabled="!worldList.length">
            <option v-if="!worldList.length" value="">（先创建大世界）</option>
            <option v-for="w in worldList" :key="w.slug" :value="w.slug">{{ w.name }} ({{ w.slug }})</option>
          </select>
          <button class="import-btn import-btn--force" type="button" :disabled="!worldList.length || !selectedWorldSlug" @click="openForcePanelFromTop">
            <span class="ib-icon">🏰</span><span>一键导入势力模板…</span>
          </button>
        </div>
      </div>
    </div>

    <!-- ============================================================
         CrudTable 大世界管理
         ============================================================ -->
    <CrudTable
      :columns="columns" :fetch-fn="fetchFn" :create-fn="createFn"
