      title="大世界管理" search-placeholder="搜索世界名称..." search-key="name"
      @refresh="handleRefresh"
    >
      <template #cell-order="{ value }"><span class="world-order">{{ value ?? 0 }}</span></template>
      <template #cell-slug="{ value }"><code class="world-slug">{{ value || '-' }}</code></template>
      <template #cell-is_active="{ value }">
        <span class="status-badge" :class="value ? 'status-badge--active' : 'status-badge--inactive'">
          {{ value ? '启用' : '停用' }}
        </span>
      </template>
    </CrudTable>

    <!-- ============================================================
         说明卡片
         ============================================================ -->
    <div class="world-tips card">
      <div class="world-tips__icon">✦</div>
      <div class="world-tips__body">
        <h3 class="world-tips__title">关于「种族」与「势力」的区分</h3>
        <p class="world-tips__text">
          <strong class="race-word">🧬 种族</strong>：生灵的血脉/物种分类（人、精灵、矮人、兽人、龙、海族、天使、虫族、德鲁伊…）。
          每个种族可进一步划分为多级亚种族，如「人族 → 中原人 / 北境蛮人 / 西域胡人 / 南疆苗人」。
          角色管理页中的「种族」字段就是从这里取的下拉选项。
        </p>
        <p class="world-tips__text">
          <strong class="force-word">🏰 势力</strong>：由各族生灵（无论种族）组成的组织团体（天剑门、暴风王国、聚元商会、圣光教会…）。
          势力同样支持多层级嵌套，如「正道联盟 → 天剑门 → 青云剑宗」。
          角色的「所属势力」字段从这里取。
        </p>
        <div class="import-actions-hint">
          <strong class="hint-title">📜 快捷导入：</strong>
          点击顶部「🧬 一键导入种族模板」或「🏰 一键导入势力模板」按钮，选择目标大世界即可。
          也可前往
          <router-link class="inline-link" to="/admin/factions">种族 / 势力管理</router-link>
          页面进行详细编辑。
        </div>
      </div>
    </div>

    <!-- ============================================================
         导入面板 Modal（种族 / 势力共用一套结构）
         ============================================================ -->
    <Teleport to="body">
      <Transition name="modal-fade">
        <div v-if="importPanelOpen" class="modal-mask" @click.self="closeImportPanel">
          <div class="import-modal">
            <div class="import-modal__corner import-modal__corner--tl"></div>
            <div class="import-modal__corner import-modal__corner--tr"></div>
            <div class="import-modal__corner import-modal__corner--bl"></div>
            <div class="import-modal__corner import-modal__corner--br"></div>

            <header class="import-modal__header">
              <div>
                <div class="modal-subtitle">
                  为大世界导入
                  <span :class="activePanel === 'race' ? 'race-word' : 'force-word'">{{ currentCategoryLabel }}模板</span>
                </div>
                <h2 class="modal-title">
                  🌌 {{ targetWorld?.name }}
                  <code class="modal-slug">/ {{ targetWorld?.slug }}</code>
