                    <div :class="['pg-title', `pg-title--${lvl}`]">
                      <span class="pg-level">{{ lvl === 'unknown' ? '?' : lvl }}</span>
                      <span class="pg-count">{{ list.length }} 项</span>
                    </div>
                    <div class="pg-items">
                      <span
                        v-for="f in list" :key="f.key || f.name" class="pg-item"
                        :title="f.description + (f.parent ? `\n【父】${f.parent}` : '')"
                      >
                        <span v-if="f.parent" class="pg-sub">└ </span>
                        {{ f.name }}
                      </span>
                    </div>
                  </div>
                </div>
              </section>

              <!-- 覆盖选项 -->
              <section class="modal-section">
                <label class="overwrite-option">
                  <input type="checkbox" v-model="importOverwrite" :disabled="importing" />
                  <span>
                    <strong>覆盖同名{{ currentCategoryLabel }}</strong>
                    <span class="help">（关=跳过同名；开=使用模板内容更新已有）</span>
                  </span>
                </label>
              </section>

              <!-- 日志 -->
              <section class="modal-section" v-if="importLog.length">
                <div class="section-title">③ 导入日志</div>
                <div class="import-log">
