              </section>
            </div>

            <footer class="import-modal__footer">
              <button class="btn btn--ghost" type="button" :disabled="importing" @click="closeImportPanel">
                {{ importLog.length ? '完成，关闭面板' : '取消' }}
              </button>
              <button
